def get_all_sources(lead_type: Optional[str] = None, country: Optional[str] = None, is_indian: Optional[bool] = None) -> List[Dict]:
    """Returns verified trade sources filtered optionally by lead type, country, and Indian focus."""
    sources: List[Dict] = []
    if lead_type in ("importer", "importers", "buyer", "buyers"):
        sources = list(IMPORTER_SOURCES)
    elif lead_type in ("supplier", "suppliers", "wb_mill", "wb_mills", "mill", "mills"):
        sources = list(SUPPLIER_SOURCES)
    else:
        sources = list(IMPORTER_SOURCES) + list(SUPPLIER_SOURCES)

    if is_indian is True:
        return [
            s for s in sources
            if s.get("is_indian") or "india" in s.get("country_coverage", "").lower()
        ]

    if country and country.lower() not in ("all", "all countries", "global", ""):
        c_low = country.lower().strip()
        filtered = [
            s for s in sources
            if c_low in s.get("country_coverage", "").lower() or s.get("country_coverage", "").lower() == "global"
        ]
        if filtered:
            return filtered

    return sources


def get_importer_sources(country: Optional[str] = None) -> List[Dict]:
    return get_all_sources(lead_type="importer", country=country)


def get_supplier_sources(country: Optional[str] = None, is_indian: Optional[bool] = None) -> List[Dict]:
    return get_all_sources(lead_type="supplier", country=country, is_indian=is_indian)


def get_indian_supplier_sources() -> List[Dict]:
    """Returns verified Indian trade councils, commodity boards, and milling registries."""
    return [
        s for s in SUPPLIER_SOURCES
        if s.get("is_indian") or "india" in s.get("country_coverage", "").lower()
    ]
